#!/usr/bin/env node
'use strict';
/*
 * Builds apps-script/Code.gs = server/core.js (the exact file the tests run) + the Sheets adapter + the entry points.
 * Code.gs contains NO secrets and NO answer keys. The keys go in a separate, private ItemBankSeed.gs (see tools/build-content.js).
 */
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const read = (p) => fs.readFileSync(path.join(root, p), 'utf8');
const banner = `/*
 * Unit 8 Family Life & Sexuality: assessment back end. GENERATED by tools/build-apps-script.js. Do not edit by hand.
 * Paste this whole file into the Apps Script editor of your Google Sheet (Extensions > Apps Script), replacing Code.gs.
 * Contains no passwords and no answer keys.
 */
`;
function buildText() {
  return banner +
  '\n/* ===== server/core.js (shared with the tests and the in-browser demo) ===== */\n' + read('server/core.js').replace(/\nif \(typeof module[\s\S]*$/, '\n') +
  '\n/* ===== server/gas/sheets-store.js ===== */\n' + read('server/gas/sheets-store.js') +
  '\n/* ===== server/gas/entry.js ===== */\n' + read('server/gas/entry.js');
}
module.exports = { buildText };
if (require.main === module) {
const out = buildText();
fs.mkdirSync(path.join(root, 'apps-script'), { recursive: true });
fs.writeFileSync(path.join(root, 'apps-script/Code.gs'), out);
console.log('wrote apps-script/Code.gs (' + out.length + ' bytes, ' + out.split('\n').length + ' lines)');
}
